"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50004"],{57032(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.instante_do_envio_fora_do_calendario","status":422,"titulo":"O instante do envio simulado est\xe1 ausente ou fora do calend\xe1rio que os limites da faixa de data alcan\xe7am"},"descricao":{"codigo":"uniplus.formulario_portavel.instante_do_envio_fora_do_calendario","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. O envio simulado (`envio`) traz um `instante` cujo dia, no `fuso` informado, fica perto demais das pontas do calend\xe1rio. Os limites da faixa de data de um campo podem ser contados do dia do envio, com deslocamento de at\xe9 150 anos ou 54.900 dias para mais ou para menos, e o dia do envio precisa comportar esse deslocamento nos dois lados: ficar a pelo menos esse intervalo de 01/01/0001 e de 31/12/9999. A mensagem \xe9 \\"O instante do envio falta ou fica fora do calend\xe1rio que os limites da faixa de data alcan\xe7am.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `envio.instante`. Nada \xe9 gravado. A propriedade `instante` ausente \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo. O fuso \xe9 conferido antes: com o fuso recusado, a recusa \xe9 a de [fuso do envio desconhecido](/erros/uniplus.formulario_portavel.fuso_do_envio_desconhecido)."],"comoResolver":["Informe um `instante` de uma data corrente, como a de um envio real, ou omita o `envio` inteiro."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);